#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr.

The CLI reads one campaign object (at most 64 MiB) and writes exactly one JSON
certificate.  Framing problems - malformed JSON, duplicate keys, non-finite
numbers, invalid UTF-8, trailing JSON, or an oversized payload - produce the
single documented error object on stdout and a zero exit status.
"""
import json
import math
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))

from eywa.offline import execute

MAX_INPUT = 64 * 1024 * 1024
INVALID_INPUT = {"error": "INVALID_INPUT"}


def pairs(items):
    """Reject duplicate keys instead of silently keeping the last value."""
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate key")
        result[key] = value
    return result


def read_request():
    """Parse stdin into a campaign object, or raise ValueError."""
    raw = sys.stdin.buffer.read(MAX_INPUT + 1)
    if len(raw) > MAX_INPUT:
        raise ValueError("input cap")
    text = raw.decode("utf-8")

    def bad_constant(value):
        raise ValueError("non-finite number")

    def finite_float(value):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError("non-finite number")
        return number

    request = json.loads(text, object_pairs_hook=pairs, parse_constant=bad_constant,
                         parse_float=finite_float)
    if not isinstance(request, dict):
        raise ValueError("campaign must be an object")
    return request


def main():
    try:
        request = read_request()
    except (ValueError, UnicodeError, RecursionError) as exc:
        print("invalid input: %s" % exc, file=sys.stderr)
        result = INVALID_INPUT
    else:
        try:
            result = execute(request)
        except (ValueError, KeyError, TypeError, AttributeError, RecursionError,
                OverflowError) as exc:                # out-of-domain campaign
            print("campaign rejected: %r: %s" % (type(exc).__name__, exc),
                  file=sys.stderr)
            result = INVALID_INPUT
    json.dump(result, sys.stdout, ensure_ascii=True, separators=(",", ":"),
              allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
PYEOF
